(function(){
var manager=document.getElementById('mediaManager');if(!manager)return;
var form=manager.closest('form'),input=document.getElementById('propertyImages'),drop=document.getElementById('mediaDropZone'),preview=document.getElementById('newMediaPreview'),grid=document.getElementById('existingMediaGrid'),status=document.getElementById('mediaStatus');
var manageUrl=manager.dataset.manageUrl,deleteUrl=manager.dataset.deleteUrl,propertyId=manager.dataset.propertyId,csrf=(form.querySelector('[name="_csrf"]')||{}).value||'';
function flash(message){status.textContent=message}
function post(data){data.set('_csrf',csrf);data.set('property_id',propertyId);return fetch(manageUrl,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded','X-Requested-With':'XMLHttpRequest'},body:new URLSearchParams(data)}).then(function(r){if(!r.ok)throw new Error(<?= json_encode(villa_ui('İşlem kaydedilemedi'),JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT) ?>);return r.json()})}
function orderExisting(){var ids=Array.from(grid.querySelectorAll('[data-media-id]')).map(function(card){return card.dataset.mediaId});var data=new URLSearchParams();data.set('action','sort');ids.forEach(function(id){data.append('media_ids[]',id)});post(data).then(function(){flash(ids.length+<?= json_encode(villa_ui(' fotoğraf · Sıralama kaydedildi'),JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT) ?>)}).catch(function(e){flash(e.message)})}
var dragging=null;
grid.addEventListener('dragstart',function(e){var card=e.target.closest('.media-card');if(!card)return;dragging=card;card.classList.add('dragging');e.dataTransfer.effectAllowed='move'});
grid.addEventListener('dragend',function(){if(dragging)dragging.classList.remove('dragging');dragging=null;orderExisting()});
grid.addEventListener('dragover',function(e){e.preventDefault();var target=e.target.closest('.media-card');if(!target||!dragging||target===dragging)return;var rect=target.getBoundingClientRect();grid.insertBefore(dragging,e.clientY<rect.top+rect.height/2?target:target.nextSibling)});
grid.addEventListener('click',function(e){var cover=e.target.closest('[data-set-cover]'),del=e.target.closest('[data-delete-media]');if(cover){var data=new URLSearchParams({action:'cover',media_id:cover.dataset.setCover});post(data).then(function(){grid.querySelectorAll('.cover-tag').forEach(function(x){x.hidden=true});cover.closest('.media-card').querySelector('.cover-tag').hidden=false;flash(<?= json_encode(villa_ui('Kapak fotoğrafı güncellendi'),JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT) ?>)}).catch(function(x){flash(x.message)})}
if(del){if(!confirm(<?= json_encode(villa_ui('Bu fotoğrafı silmek istediğinize emin misiniz?'),JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT) ?>))return;var f=new FormData();f.append('_csrf',csrf);f.append('property_id',propertyId);f.append('media_id',del.dataset.deleteMedia);fetch(deleteUrl,{method:'POST',body:f}).then(function(r){if(!r.ok)throw new Error(<?= json_encode(villa_ui('Fotoğraf silinemedi'),JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT) ?>);del.closest('.media-card').remove();flash(<?= json_encode(villa_ui('Fotoğraf silindi'),JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT) ?>)}).catch(function(x){flash(x.message)})}});
var files=[];
function setFiles(list){files=Array.from(list).slice(0,30);var transfer=new DataTransfer();files.forEach(function(f){transfer.items.add(f)});input.files=transfer.files;renderPreview()}
function renderPreview(){preview.innerHTML='';files.forEach(function(file,index){var card=document.createElement('article');card.className='media-card';card.draggable=true;card.dataset.index=index;var img=document.createElement('img');img.alt=file.name;img.src=URL.createObjectURL(file);var label=document.createElement('div');label.className='media-help';label.textContent=file.name;card.append(img,label);preview.append(card)});
preview.querySelectorAll('.media-card').forEach(function(card){card.addEventListener('dragstart',function(e){card.classList.add('dragging');e.dataTransfer.setData('text/plain',card.dataset.index)});card.addEventListener('dragend',function(){card.classList.remove('dragging')})});
}
preview.addEventListener('dragover',function(e){e.preventDefault()});preview.addEventListener('drop',function(e){e.preventDefault();var from=Number(e.dataTransfer.getData('text/plain'));var target=e.target.closest('.media-card');if(!target||!Number.isInteger(from))return;var to=Number(target.dataset.index);var moved=files.splice(from,1)[0];files.splice(to,0,moved);setFiles(files)});
